def transform(grid):
    """Fill the background-colored interior of fully outlined rectangles with 4."""
    out = [row[:] for row in grid]
    counts = Counter(value for row in grid for value in row)
    background, line = [value for value, _ in counts.most_common(2)]
    height, width = len(grid), len(grid[0])

    for top in range(height - 2):
        for bottom in range(top + 2, height):
            for left in range(width - 2):
                for right in range(left + 2, width):
                    if any(grid[r][c] != background
                           for r in range(top + 1, bottom)
                           for c in range(left + 1, right)):
                        continue
                    if any(grid[top][c] != line or grid[bottom][c] != line
                           for c in range(left, right + 1)):
                        continue
                    if any(grid[r][left] != line or grid[r][right] != line
                           for r in range(top + 1, bottom)):
                        continue
                    for r in range(top + 1, bottom):
                        for c in range(left + 1, right):
                            out[r][c] = 4
    return out
